#include "ExpectedErrors.hpp"

#include <boost/log/trivial.hpp>

#include <algorithm>
#include <mutex>

namespace Slic3r::GUI::JusPrin {

namespace {

std::mutex                       g_mutex;
std::map<std::string, unsigned>  g_counts;

} // namespace

const std::vector<ExpectedError>& expected_errors()
{
    // The failures of a request to the AI (ProviderAgent::http_error). Each
    // has a test in tests/agent/test_provider_agent.cpp.
    static const std::vector<ExpectedError> kTable = {
        {"update_required", "The app is older than the oldest release JusPrin Cloud still serves.",
         "This version of JusPrin can no longer connect to JusPrin accounts.", "Get the new version, from the button."},
        {"invalid_credentials",
         "The person's JusPrin sign-in ended, or the AI provider rejected the person's own API key.",
         "Their sign-in has ended, or the API key was rejected.", "Sign in again, or update the key."},
        {"credits_exhausted", "The person is out of credits.", "They are out of credits.",
         "Get more credits, from the button."},
        {"request_too_large", "The chat, with its pictures and files, is larger than the AI service accepts.",
         "The request was too large for the AI service.",
         "Start a new chat, or send fewer pictures. The message does not say so today."},
        {"rate_limited", "The AI provider or JusPrin Cloud is limiting how fast this person may send.",
         "The AI service is rate limited.", "Wait a moment, then Retry."},
        {"service_overloaded", "The AI provider is overloaded.", "The AI service is overloaded.",
         "Wait a moment, then Retry."},
        {"service_unavailable", "The AI provider is down, or JusPrin Cloud cannot reach it.",
         "The AI service is temporarily unavailable.", "Retry, now or a little later."},
        {"timeout", "The AI provider took too long to answer, or the connection to it stalled.",
         "The AI request timed out.", "Retry."},
        {"network_error", "This computer could not reach the AI service: no network, or the connection failed.",
         "The AI request could not reach the service.", "Check the network, then Retry."},
    };
    return kTable;
}

const ExpectedError* expected_error(std::string_view code)
{
    const auto& table = expected_errors();
    const auto  found = std::find_if(table.begin(), table.end(), [code](const ExpectedError& e) { return e.code == code; });
    return found == table.end() ? nullptr : &*found;
}

void count_expected(std::string_view code)
{
    unsigned count = 0;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        count = ++g_counts[std::string(code)];
    }
    BOOST_LOG_TRIVIAL(info) << "JusPrin expected error: " << code << ", " << count << " this run";
}

std::map<std::string, unsigned> expected_error_counts()
{
    std::lock_guard<std::mutex> lock(g_mutex);
    return g_counts;
}

} // namespace Slic3r::GUI::JusPrin

