    50	            const json input = json::parse(item.at("arguments").get<std::string>(), nullptr, false);
    51	            blocks.push_back(json{{"type", "tool_use"}, {"id", anthropic_tool_id(item.at("call_id").get<std::string>())},
    52	                                  {"name", item.at("name")}, {"input", input.is_object() ? input : json::object()}});
    53	        }
    54	    }
    55	    return blocks;
    56	}
