 60	std::string keep_gcode_copy(const std::string& project_dir, const std::string& hash, const std::string& source,
 61	                            std::size_t keep)
 62	{
 63	    namespace fs = std::filesystem;
 64	    if (hash.size() != 64 || hash.find_first_not_of("0123456789abcdef") != std::string::npos)
 65	        throw std::logic_error("a kept G-code is named by its SHA-256, not " + hash);
 66	    const fs::path dir = kept_gcode_dir(project_dir);
 67	    fs::create_directories(dir);
 68	    const fs::path copy = dir / (hash + ".gcode");
 69	    if (fs::exists(copy)) {
 70	        // The same bytes left again: it is the newest copy now.
 71	        fs::last_write_time(copy, fs::file_time_type::clock::now());
 72	    } else {
 73	        const fs::path pending = dir / (hash + ".pending");
 74	        fs::copy_file(fs::u8path(source), pending, fs::copy_options::overwrite_existing);
 75	        fs::rename(pending, copy);
 76	    }
 77	
 78	    std::vector<std::pair<fs::file_time_type, fs::path>> copies;
 79	    for (const fs::directory_entry& entry : fs::directory_iterator(dir))
 80	        if (entry.is_regular_file() && entry.path().extension() == ".gcode")
 81	            copies.emplace_back(entry.last_write_time(), entry.path());
 82	    if (copies.size() > keep) {
 83	        std::sort(copies.begin(), copies.end(), [](const auto& left, const auto& right) { return left.first > right.first; });
 84	        for (std::size_t index = keep; index < copies.size(); ++index)
 85	            if (copies[index].second != copy) {
 86	                // A G-code's package goes with it.
 87	                const std::string pruned = copies[index].second.stem().u8string();
 88	                fs::remove(copies[index].second);
 89	                fs::remove(dir / (pruned + ".gcode.3mf"));
 90	                fs::remove(dir / (pruned + ".config.3mf"));
 91	            }
 92	    }
 93	    return copy.u8string();
 94	}
 95	
 96	std::string kept_gcode_copy(const std::string& project_dir, const std::string& hash)
 97	{
 98	    const std::filesystem::path copy = kept_gcode_dir(project_dir) / (hash + ".gcode");
 99	    return std::filesystem::exists(copy) ? copy.u8string() : std::string();
100	}
101	
102	std::string keep_gcode_package(const std::string& project_dir, const std::string& hash, const std::string& package,
103	                               const std::string& config)
104	{
105	    namespace fs = std::filesystem;
106	    if (kept_gcode_copy(project_dir, hash).empty())
107	        throw std::logic_error("a package is kept beside its G-code's copy, and G-code " + hash + " has none");
108	    const fs::path dir = kept_gcode_dir(project_dir);
109	    const auto keep = [&dir](const std::string& source, const fs::path& target) {
110	        const fs::path pending = dir / (target.filename().u8string() + ".pending");
111	        fs::copy_file(fs::u8path(source), pending, fs::copy_options::overwrite_existing);
112	        fs::rename(pending, target);
113	    };
114	    keep(package, dir / (hash + ".gcode.3mf"));
115	    // A config left from an earlier cloud send belongs to that send's package.
116	    if (config.empty())
117	        fs::remove(dir / (hash + ".config.3mf"));
118	    else
119	        keep(config, dir / (hash + ".config.3mf"));
120	    return sha256_file_hex((dir / (hash + ".gcode.3mf")).u8string());
121	}
122	
123	std::optional<KeptPackage> kept_gcode_package(const std::string& project_dir, const std::string& hash)
124	{
125	    namespace fs = std::filesystem;
126	    const fs::path dir     = kept_gcode_dir(project_dir);
127	    const fs::path package = dir / (hash + ".gcode.3mf");
128	    if (kept_gcode_copy(project_dir, hash).empty() || !fs::exists(package))
129	        return std::nullopt;
130	    const fs::path config = dir / (hash + ".config.3mf");
131	    return KeptPackage{package.u8string(), fs::exists(config) ? config.u8string() : std::string()};
132	}
